SELECT * FROM chapter_content_variants
 WHERE chapter_id = #{chapterId}
   AND source_variant_id IS NOT DISTINCT FROM #{sourceVariantId}
   AND language_code = #{languageCode} AND source_content_hash = #{sourceContentHash}
   AND content_hash = #{contentHash}
 ORDER BY id DESC LIMIT 1

SELECT * FROM chapter_content_variants
 WHERE chapter_id = #{chapterId} AND source_variant_id = #{sourceVariantId}
   AND variant_type = 'TRANSLATION' AND language_code = #{languageCode}
   AND source_content_hash = #{sourceContentHash}
   AND translation_status = 'COMPLETED'
 ORDER BY id DESC LIMIT 1

